INSERT INTO files (code, full_code, title, tags, inventory_id)
SELECT mf.code, 'ДАХеО' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code, mf.title, mf.tags, i.id
FROM mf JOIN fonds fo ON fo.code = mf.fond JOIN arch ON arch.id = fo.archive_id JOIN inventories i ON i.fond_id = fo.id AND i.code = mf.inv
WHERE NOT EXISTS (SELECT 1 FROM files x WHERE x.inventory_id = i.id AND x.code = mf.code);
INSERT INTO file_years (file_id, start_year, end_year) SELECT f.id, split_part(r, '-', 1)::int, split_part(r, '-', 2)::int
FROM mf JOIN files f ON f.full_code = 'ДАХеО' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code, unnest(string_to_array(mf.years, ',')) r
WHERE mf.years <> '' AND NOT EXISTS (SELECT 1 FROM file_years y WHERE y.file_id = f.id) ON CONFLICT DO NOTHING;
DO $$ BEGIN IF (SELECT count(*) FROM mf JOIN files f ON f.full_code = 'ДАХеО' || '-' || mf.fond || '-' || mf.inv || '-' || mf.code) <> (SELECT count(*) FROM mf) THEN RAISE EXCEPTION 'A: not all files created (inventory missing?)'; END IF; END $$;

-- B. «метрична книга» + kind tags
CREATE TEMP TABLE mt(full_code text, tags text[]); INSERT INTO mt VALUES ('ДАХеО-259-24-18',ARRAY['метрична книга','народження','шлюб','смерть']::text[]),
('ДАХеО-259-24-37',ARRAY['метрична книга','народження','шлюб','смерть']::text[]),
('ДАХеО-316-2-18',ARRAY['метрична книга','народження','шлюб']::text[]),
('ДАХеО-169-1-19',ARRAY['метрична книга','народження','шлюб','смерть']::text[]),
('ДАХеО-113-1-30',ARRAY['метрична книга','розлучення']::text[]);
UPDATE files f SET tags = (SELECT array_agg(DISTINCT x) FROM unnest(f.tags || mt.tags) x) FROM mt WHERE f.full_code = mt.full_code AND NOT ('метрична книга' = ANY(f.tags));

-- C. bare years
CREATE TEMP TABLE my(full_code text, years text); INSERT INTO my VALUES ('ДАХеО-259-24-18','1866-1866'),('ДАХеО-259-24-37','1901-1901');
INSERT INTO file_years (file_id, start_year, end_year) SELECT f.id, split_part(r, '-', 1)::int, split_part(r, '-', 2)::int FROM my JOIN files f ON f.full_code = my.full_code, unnest(string_to_array(my.years, ',')) r WHERE NOT EXISTS (SELECT 1 FROM file_years y WHERE y.file_id = f.id) ON CONFLICT DO NOTHING;

-- C. bare titles
CREATE TEMP TABLE mtt(full_code text, title text); INSERT INTO mtt VALUES ('ДАХеО-259-24-18','Метрична книга. Церква Покрови Пресвятої Богородиці, м. Каховка Дніпровського пов. Каховської вол.'),
('ДАХеО-259-24-37','Метрична книга. Церква Покрови Пресвятої Богородиці, м. Каховка Дніпровського пов. Каховської вол.');
UPDATE files f SET title = mtt.title FROM mtt WHERE f.full_code = mtt.full_code AND coalesce(f.title, '') = '';

-- D. fond year ranges
CREATE TEMP TABLE fy(fond text, s int, e int); INSERT INTO fy VALUES ('111',1802,1918),('113',1836,1867),('124',1852,1873),('137',1721,1921),('141',1863,1874),('169',1782,1921),('198',1782,1909),('207',1782,1920),('220',1855,1867),('259',1793,1921),('262',1855,1869),('264',1867,1874),('269',1861,1874),('278',1874,1874),('316',1841,1921),('323',1899,1917);
INSERT INTO fond_years (fond_id, start_year, end_year) SELECT fo.id, fy.s, fy.e FROM fy JOIN fonds fo ON fo.code = fy.fond JOIN arch ON arch.id = fo.archive_id WHERE NOT EXISTS (SELECT 1 FROM fond_years y WHERE y.fond_id = fo.id) ON CONFLICT DO NOTHING;

-- E. glued duplicates (identical title + span as a catalog sibling)
CREATE TEMP TABLE mg(src text, dst text); INSERT INTO mg VALUES ('ДАХеО-137-15-1603','ДАХеО-137-15-1');
CREATE TEMP TABLE g AS SELECT m.*, s.id AS src_id, d.id AS dst_id FROM mg m JOIN files s ON s.full_code = m.src JOIN files d ON d.full_code = m.dst;
DO $$ BEGIN IF (SELECT count(*) FROM g) <> (SELECT count(*) FROM mg) THEN RAISE EXCEPTION 'E: source or target missing'; END IF; END $$;
DO $$ BEGIN IF EXISTS (SELECT 1 FROM g JOIN files s ON s.id = g.src_id JOIN files d ON d.id = g.dst_id WHERE s.title IS DISTINCT FROM d.title OR (SELECT min(start_year)||'-'||max(end_year) FROM file_years WHERE file_id = s.id) IS DISTINCT FROM (SELECT min(start_year)||'-'||max(end_year) FROM file_years WHERE file_id = d.id)) THEN RAISE EXCEPTION 'E: not an exact duplicate'; END IF; END $$;
DELETE FROM online_copies oc USING g WHERE oc.file_id = g.src_id AND EXISTS (SELECT 1 FROM online_copies d WHERE d.file_id = g.dst_id AND d.resource_id = oc.resource_id AND d.url = oc.url AND d.parsed = oc.parsed);
UPDATE online_copies oc SET file_id = g.dst_id FROM g WHERE oc.file_id = g.src_id;
INSERT INTO file_authors (file_id, author_id) SELECT g.dst_id, fa.author_id FROM file_authors fa JOIN g ON fa.file_id = g.src_id ON CONFLICT DO NOTHING; DELETE FROM file_authors fa USING g WHERE fa.file_id = g.src_id;
UPDATE file_actions x SET file_id = g.dst_id FROM g WHERE x.file_id = g.src_id; DELETE FROM files f USING g WHERE f.id = g.src_id;

